147	  isAbortedError(error: unknown): boolean {
148	    return error instanceof DOMException && error.name === "AbortError";
149	  }
150	
151	  dispose(): void {
152	    this._fetchAbortController?.abort();
153	    this._fetchAbortController = null;
154	  }
