476	      this._appendItems(response.items);
477	      this._feedState = {
478	        nextOffset: response.nextOffset,
479	        hasMore: response.hasMore,
480	      };
481	      this._syncRootState();
482	      this._syncPaginationVisibility();
483	      this._attachSentinel();
484	    } catch (error) {
485	      if (error instanceof DOMException && error.name === "AbortError") return;
486	      throw error;
487	    } finally {
488	      this._abortController = null;
489	      if (grid) delete grid.dataset.loading;
490	    }
491	  }
