521	  private readonly _handleScroll = (): void => {
522	    if (!this._feedState.hasMore) return;
523	    if (this._loading) return;
524	    const list = this._elements.gridList;
525	    if (!list) return;
526	    const thresholdReached = this._isThresholdReached(list);
527	    if (!thresholdReached) {
528	      this._thresholdArmed = true;
529	      return;
530	    }
531	    if (!this._thresholdArmed) return;
532	    this._thresholdArmed = false;
533	    void this._loadMore();
